const bones: [string, Translation, string[]][] = [
  ['parietal-bone', [
    'The paired parietal bones form much of the roof and upper sides of the braincase. They meet at the sagittal suture and border the frontal, temporal and occipital bones.',
    'De två hjässbenen bildar stora delar av skalltaket och skallens övre sidor. De möts i sutura sagittalis och gränsar till pannbenet, tinningbenen och nackbenet.',
    'Die beiden Scheitelbeine bilden große Teile des Schädeldachs und der oberen Seitenwände. Sie treffen an der Sagittalnaht zusammen und grenzen an Stirn-, Schläfen- und Hinterhauptsbein.',
    'Los dos parietales forman gran parte del techo y los lados superiores del cráneo. Se unen en la sutura sagital y limitan con frontal, temporales y occipital.',
    'Ossa parietalia paria tectum et latera superiora cranii constituunt. In sutura sagittali conveniunt et ossibus frontali, temporalibus et occipitali adiacent.',
  ], ['frontal-bone', 'temporal-bone', 'occipital-bone']],
  ['temporal-bone', [
    'The temporal bone forms the lower side and part of the skull base. It houses the middle and inner ear; its mandibular fossa and articular eminence contribute to the jaw joint.',
    'Tinningbenet bildar skallens nedre sida och en del av skallbasen. Det rymmer mellan- och innerörat; fossa mandibularis och eminentia articularis ingår i käkleden.',
    'Das Schläfenbein bildet die untere Schädelwand und einen Teil der Schädelbasis. Es beherbergt Mittel- und Innenohr; Unterkiefergrube und Gelenkhöcker gehören zum Kiefergelenk.',
    'El temporal forma la pared inferior lateral y parte de la base craneal. Aloja el oído medio e interno; su fosa mandibular y eminencia articular participan en la articulación temporomandibular.',
    'Os temporale latus inferius et partem basis cranii format. Aurem mediam et internam continet; fossa mandibularis et eminentia articularis ad articulationem temporomandibularem pertinent.',
  ], ['tmj', 'articular-fossa', 'articular-eminence', 'zygomatic-bone', 'hyoid-bone']],
  ['zygomatic-bone', [
    'The zygomatic bone forms the cheek prominence and part of the outer orbital wall. Together with the temporal bone it forms the zygomatic arch, which provides attachment for masseter.',
    'Okbenet bildar kindens beniga utskjutning och en del av ögonhålans yttre vägg. Tillsammans med tinningbenet bildar det okbågen, där masseter har sitt ursprung.',
    'Das Jochbein bildet den Wangenknochen und einen Teil der äußeren Augenhöhlenwand. Mit dem Schläfenbein bildet es den Jochbogen, an dem der Masseter entspringt.',
    'El cigomático forma la prominencia de la mejilla y parte de la pared lateral de la órbita. Con el temporal forma el arco cigomático, origen del masetero.',
    'Os zygomaticum prominentiam genae et partem parietis lateralis orbitae format. Cum osse temporali arcum zygomaticum constituit, unde masseter oritur.',
  ], ['temporal-bone', 'maxilla', 'masseter']],
  ['palatine-bone', [
    'Each palatine bone has horizontal and perpendicular plates. The paired horizontal plates form the back of the hard palate; other parts contribute to the nasal cavity and a small area of the orbit.',
    'Varje gomben har en horisontell och en lodrät platta. De horisontella plattorna bildar hårda gommens bakre del; övriga delar bidrar till näshålan och ett litet område i ögonhålan.',
    'Jedes Gaumenbein besitzt eine horizontale und eine senkrechte Platte. Die horizontalen Platten bilden den hinteren harten Gaumen; weitere Teile gehören zur Nasenhöhle und einem kleinen Orbitaabschnitt.',
    'Cada palatino tiene una lámina horizontal y otra perpendicular. Las láminas horizontales forman la parte posterior del paladar duro; otras partes contribuyen a la cavidad nasal y una pequeña zona de la órbita.',
    'Os palatinum laminas horizontalem et perpendicularem habet. Laminae horizontales partem posteriorem palati duri formant; aliae partes ad cavitatem nasi et parvam regionem orbitae pertinent.',
  ], ['maxilla', 'vomer', 'sphenoid-bone']],
  ['nasal-bone', [
    'The paired nasal bones form the bony bridge of the nose, between the frontal bone and the maxillae. The flexible lower nose is mainly cartilage, which is not shown here.',
    'De två näsbenen bildar näsryggens beniga del mellan pannbenet och överkäksbenen. Näsans rörliga nedre del består främst av brosk, som inte visas här.',
    'Die beiden Nasenbeine bilden den knöchernen Nasenrücken zwischen Stirnbein und Oberkiefer. Der bewegliche untere Nasenteil besteht überwiegend aus hier nicht dargestelltem Knorpel.',
    'Los dos nasales forman el puente óseo de la nariz entre el frontal y los maxilares. La parte inferior flexible es principalmente cartílago, que no se muestra aquí.',
    'Ossa nasalia paria dorsum osseum nasi inter os frontale et maxillas formant. Pars inferior mobilis nasi praecipue cartilagine constat, quae hic non ostenditur.',
  ], ['frontal-bone', 'maxilla', 'ethmoid-bone']],
  ['lacrimal-bone', [
    'The lacrimal bone is a small bone in the anterior part of the inner orbital wall. It helps form the passage for tear drainage towards the nasal cavity.',
    'Tårbenet är ett litet ben i främre delen av ögonhålans inre vägg. Det bidrar till passagen där tårvätska leds mot näshålan.',
    'Das Tränenbein ist ein kleiner Knochen im vorderen Abschnitt der inneren Augenhöhlenwand. Es begrenzt den Abflussweg der Tränen zur Nasenhöhle.',
    'El lagrimal es un pequeño hueso en la parte anterior de la pared medial de la órbita. Contribuye al conducto por el que las lágrimas drenan hacia la cavidad nasal.',
    'Os lacrimale parvum os in parte anteriore parietis medialis orbitae est. Viam qua lacrimae ad cavitatem nasi fluunt partim format.',
  ], ['maxilla', 'ethmoid-bone', 'inferior-nasal-concha']],
  ['inferior-nasal-concha', [
    'The inferior nasal concha is an independent curved bone on the lower lateral wall of the nasal cavity. Its mucosal covering increases the surface available to warm, humidify and filter inhaled air.',
    'Den nedre näsmusslan är ett eget böjt ben på näshålans nedre sidovägg. Slemhinnan som täcker benet ökar ytan som värmer, fuktar och filtrerar inandningsluften.',
    'Die untere Nasenmuschel ist ein eigenständiger gebogener Knochen an der unteren seitlichen Nasenwand. Ihre Schleimhaut vergrößert die Fläche zum Erwärmen, Befeuchten und Filtern der Atemluft.',
    'La concha nasal inferior es un hueso curvo independiente en la pared lateral inferior de la cavidad nasal. Su mucosa aumenta la superficie para calentar, humidificar y filtrar el aire inspirado.',
    'Concha nasalis inferior os curvatum proprium in pariete laterali inferiore cavitatis nasi est. Tunica mucosa superficiem ad aerem inspiratum calefaciendum, humidificandum et purgandum auget.',
  ], ['maxilla', 'ethmoid-bone', 'vomer']],
  ['frontal-bone', [
    'The frontal bone forms the forehead, the roofs of the orbits and part of the anterior skull base. It meets the parietal bones at the coronal suture; its frontal sinuses are not separately modeled here.',
    'Pannbenet bildar pannan, ögonhålornas tak och en del av främre skallbasen. Det möter hjässbenen i sutura coronalis; pannbihålorna är inte separat modellerade här.',
    'Das Stirnbein bildet Stirn, Augenhöhlendächer und einen Teil der vorderen Schädelbasis. Es trifft an der Kranznaht auf die Scheitelbeine; die Stirnhöhlen sind hier nicht separat modelliert.',
    'El frontal forma la frente, los techos de las órbitas y parte de la base craneal anterior. Se une a los parietales en la sutura coronal; los senos frontales no se modelan por separado.',
    'Os frontale frontem, tecta orbitarum et partem basis cranii anterioris format. In sutura coronali ossibus parietalibus iungitur; sinus frontales hic separatim non finguntur.',
  ], ['parietal-bone', 'nasal-bone', 'ethmoid-bone']],
  ['occipital-bone', [
    'The occipital bone forms the back and lower rear of the braincase. The foramen magnum transmits the spinal cord, and the occipital condyles articulate with the first cervical vertebra.',
    'Nackbenet bildar skallens bakre del och bakre skallbas. Ryggmärgen passerar genom foramen magnum, och nackbenets kondyler bildar leder med den första halskotan.',
    'Das Hinterhauptsbein bildet den hinteren Schädel und die hintere Schädelbasis. Durch das große Hinterhauptsloch zieht das Rückenmark; die Hinterhauptskondylen artikulieren mit dem ersten Halswirbel.',
    'El occipital forma la parte posterior e inferior del cráneo. El foramen magno permite el paso de la médula espinal y los cóndilos occipitales articulan con la primera vértebra cervical.',
    'Os occipitale partem posteriorem et inferiorem cranii format. Medulla spinalis per foramen magnum transit; condyli occipitales cum vertebra cervicali prima articulantur.',
  ], ['parietal-bone', 'temporal-bone', 'hypoglossal-canal', 'jugular-foramen']],
  ['sphenoid-bone', [
    'The sphenoid is a central skull-base bone that contributes to the orbits and cranial floor. Its pterygoid processes provide muscle attachments; the superior orbital fissure, foramen rotundum and foramen ovale carry V1, V2 and V3.',
    'Kilbenet ligger centralt i skallbasen och bidrar till ögonhålorna och skallhålans golv. Dess vingutskott ger muskelfästen; fissura orbitalis superior, foramen rotundum och foramen ovale leder V1, V2 och V3.',
    'Das Keilbein liegt zentral in der Schädelbasis und bildet Teile der Orbita und des Schädelbodens. Seine Flügelfortsätze dienen als Muskelansatz; obere Orbitafissur, Foramen rotundum und Foramen ovale führen V1, V2 und V3.',
    'El esfenoides ocupa el centro de la base craneal y contribuye a las órbitas y al suelo craneal. Sus procesos pterigoideos dan inserción muscular; la fisura orbitaria superior y los agujeros redondo y oval transmiten V1, V2 y V3.',
    'Os sphenoidale in media basi cranii situm ad orbitas et fundum cranii pertinet. Processus pterygoidei musculis insertiones praebent; fissura orbitalis superior, foramen rotundum et foramen ovale V1, V2 et V3 transmittunt.',
  ], ['medial-pterygoid', 'lateral-pterygoid', 'superior-orbital-fissure', 'foramen-rotundum', 'foramen-ovale']],
  ['ethmoid-bone', [
    'The ethmoid lies between the orbits and the upper nasal cavity. It forms part of the nasal septum and medial orbital walls; its cribriform plate carries olfactory nerve fibers.',
    'Silbenet ligger mellan ögonhålorna och näshålans övre del. Det bildar delar av nässkiljeväggen och ögonhålornas inre väggar; luktnerver passerar genom lamina cribrosa.',
    'Das Siebbein liegt zwischen Augenhöhlen und oberer Nasenhöhle. Es bildet Teile der Nasenscheidewand und der medialen Orbitawände; Riechnervenfasern ziehen durch die Siebplatte.',
    'El etmoides se sitúa entre las órbitas y la cavidad nasal superior. Forma parte del tabique nasal y las paredes mediales orbitarias; su lámina cribosa da paso a fibras olfatorias.',
    'Os ethmoidale inter orbitas et cavitatem nasi superiorem situm est. Partes septi nasi et parietum medialium orbitarum format; fibrae olfactoriae per laminam cribrosam transeunt.',
  ], ['vomer', 'frontal-bone', 'lacrimal-bone', 'inferior-nasal-concha']],
  ['vomer', [
    'The vomer is a midline bone forming the lower and posterior part of the bony nasal septum. It separates the right and left nasal passages and meets the ethmoid superiorly.',
    'Plogbenet ligger i mittlinjen och bildar den beniga nässkiljeväggens nedre och bakre del. Det skiljer höger och vänster näsgång och möter silbenet upptill.',
    'Das Pflugscharbein liegt in der Mittellinie und bildet den unteren hinteren Teil der knöchernen Nasenscheidewand. Es trennt beide Nasengänge und trifft oben auf das Siebbein.',
    'El vómer es un hueso de la línea media que forma la parte inferior y posterior del tabique nasal óseo. Separa ambos conductos nasales y se une superiormente al etmoides.',
    'Vomer os medianum est quod partem inferiorem et posteriorem septi nasi ossei format. Meatus nasi dextrum et sinistrum separat et superiora versus os ethmoidale attingit.',
  ], ['ethmoid-bone', 'palatine-bone', 'maxilla']],
];

const entries: Record<string, Entry> = Object.fromEntries(bones.map(([key, summary, related]) => [key, { summary, related, sources: [skull] }]));
entries['venous-drainage'] = {
  summary: ['Veins return blood from the teeth, jaws and face. Dental veins connect with larger facial and deep venous pathways, including the pterygoid plexus and internal jugular vein.', 'Vener för blod tillbaka från tänder, käkar och ansikte. Dentala vener ansluter till större ytliga och djupa venförlopp, bland annat plexus pterygoideus och v. jugularis interna.', 'Venen führen Blut aus Zähnen, Kiefern und Gesicht zurück. Dentale Venen stehen mit größeren oberflächlichen und tiefen Abflusswegen wie Plexus pterygoideus und innerer Drosselvene in Verbindung.', 'Las venas devuelven sangre de dientes, maxilares y cara. Las venas dentales conectan con vías faciales y profundas, incluidos el plexo pterigoideo y la yugular interna.', 'Venae sanguinem a dentibus, maxillis et facie reducunt. Venae dentales cum viis facialibus et profundis, inter quas plexus pterygoideus et vena jugularis interna, coniunguntur.'],
  related: ['inferior-alveolar-vein', 'pterygoid-plexus', 'internal-jugular-vein'], sources: [{ title: 'NCBI: Pterygoid plexus', url: 'https://www.ncbi.nlm.nih.gov/books/NBK555896/' }],
};
entries['hyoid-bone'] = {
  summary: [
    'The hyoid is a U-shaped bone in the upper neck, below the mandible. It has a body, greater horns and lesser horns. It does not form a joint with another bone: muscles, the stylohyoid ligaments and membranes suspend it between the skull, mandible and larynx.',
    'Tungbenet är ett U-format ben i övre halsen, nedanför underkäken. Det har en kropp samt större och mindre horn. Det bildar ingen led med något annat ben: muskler, ligamenta stylohyoidea och membran håller det mellan skallen, underkäken och struphuvudet.',
    'Das Zungenbein ist ein U-förmiger Knochen im oberen Hals unter dem Unterkiefer. Es besitzt Körper, große und kleine Hörner. Es artikuliert mit keinem anderen Knochen: Muskeln, Stylohyoidbänder und Membranen halten es zwischen Schädel, Unterkiefer und Kehlkopf.',
    'El hioides es un hueso en U en el cuello superior, bajo la mandíbula. Tiene cuerpo, astas mayores y menores. No articula con otro hueso: músculos, ligamentos estilohioideos y membranas lo suspenden entre cráneo, mandíbula y laringe.',
    'Os hyoideum os U simile in parte superiore colli infra mandibulam est. Corpus et cornua maiora minoraque habet. Cum alio osse non articulatur: musculi, ligamenta stylohyoidea et membranae illud inter cranium, mandibulam et laryngem suspendunt.',
  ],
  function: [
    'An attachment platform for muscles of the tongue, floor of the mouth and larynx. Suprahyoid and infrahyoid muscles coordinate its position during swallowing and speech; some suprahyoid muscles assist jaw opening when the hyoid is stabilized.',
    'Fäste för muskler till tungan, munbotten och struphuvudet. Suprahyoidala och infrahyoidala muskler samordnar läget vid sväljning och tal; vissa suprahyoidala muskler hjälper till att öppna käken när tungbenet är stabiliserat.',
    'Ansatz für Zungen-, Mundboden- und Kehlkopfmuskeln. Supra- und infrahyoidale Muskeln koordinieren seine Lage beim Schlucken und Sprechen; einige suprahyoidale Muskeln helfen bei stabilisiertem Zungenbein, den Kiefer zu öffnen.',
    'Da inserción a músculos de lengua, suelo de la boca y laringe. Los músculos supra e infrahioideos coordinan su posición al tragar y hablar; algunos suprahioideos ayudan a abrir la mandíbula cuando el hioides está estabilizado.',
    'Musculis linguae, fundi oris et laryngis insertionem praebet. Musculi supra- et infrahyoidei situm eius in deglutitione et sermone moderantur; nonnulli suprahyoidei mandibulam deprimunt dum os hyoideum stabilitur.',
  ], related: ['mandible', 'temporal-bone'], sources: [hyoid, supra],
};

const groups: [string, Translation, string[], typeof skull][] = [
  ['dental-anatomy', ['Explore the teeth, their supporting tissues, jaws, skull, muscles, nerves and vessels. Select a structure for its anatomy and related structures.', 'Utforska tänder, stödjevävnader, käkar, skalle, muskler, nerver och kärl. Välj en struktur för att läsa om dess anatomi och samband.', 'Erkunden Sie Zähne, Haltegewebe, Kiefer, Schädel, Muskeln, Nerven und Gefäße. Wählen Sie eine Struktur für Anatomie und Beziehungen.', 'Explore dientes, tejidos de soporte, maxilares, cráneo, músculos, nervios y vasos. Seleccione una estructura para conocer su anatomía y relaciones.', 'Dentes, textus sustentantes, maxillas, cranium, musculos, nervos et vasa explora. Structuram elige ut anatomiam et nexus videas.'], ['maxilla', 'mandible', 'periodontium', 'nerves'], skull],
  ['maxillary-dentition', ['The upper permanent dental arch contains incisors, canines, premolars and molars. Each side has eight positions, including a third molar; eruption and presence vary.', 'Överkäkens permanenta tandbåge innehåller incisiver, hörntänder, premolarer och molarer. Varje sida har åtta positioner, inklusive en visdomstand; eruption och förekomst varierar.', 'Der permanente Oberkieferzahnbogen umfasst Schneide-, Eck-, Prämolar- und Molarzähne. Jede Seite hat acht Positionen einschließlich Weisheitszahn; Durchbruch und Vorhandensein variieren.', 'La arcada superior permanente contiene incisivos, caninos, premolares y molares. Cada lado tiene ocho posiciones, incluido el tercer molar; presencia y erupción varían.', 'Arcus dentalis superior permanens incisivos, caninos, praemolares et molares continet. Octo loca in quoque latere sunt cum dente serotino; praesentia et eruptio variant.'], ['maxilla', 'mandibular-dentition'], skull],
  ['mandibular-dentition', ['The lower permanent dental arch is supported by the mandible and meets the upper arch during biting. Each side has eight tooth positions, including a third molar; not everyone has all teeth.', 'Underkäkens permanenta tandbåge stöds av mandibeln och möter överkäkens tandbåge vid sammanbitning. Varje sida har åtta tandpositioner, inklusive en visdomstand; alla har inte samtliga tänder.', 'Der permanente Unterkieferzahnbogen wird von der Mandibula getragen und trifft beim Zubeißen auf den Oberkiefer. Jede Seite hat acht Zahnpositionen einschließlich Weisheitszahn; nicht jeder hat alle Zähne.', 'La arcada inferior permanente se apoya en la mandíbula y contacta con la superior al morder. Cada lado tiene ocho posiciones, incluido el tercer molar; no todas las personas tienen todos los dientes.', 'Arcus dentalis inferior permanens mandibula sustentatur et in morsu arcum superiorem attingit. Octo loca dentium in quoque latere sunt cum dente serotino; non omnes homines omnes dentes habent.'], ['mandible', 'maxillary-dentition'], skull],
  ['neurovascular', ['Nerves carry sensory and motor signals; arteries deliver blood and veins drain it. The dental branches are displayed separately from other cranial nerves to make their courses easier to follow.', 'Nerver leder sensoriska och motoriska signaler; artärer tillför blod och vener för det tillbaka. De dentala grenarna visas separat från övriga kranialnerver för tydligare förlopp.', 'Nerven leiten sensible und motorische Signale; Arterien führen Blut zu, Venen führen es ab. Dentale Äste werden für bessere Übersicht getrennt von anderen Hirnnerven angezeigt.', 'Los nervios transmiten señales sensitivas y motoras; las arterias aportan sangre y las venas la drenan. Las ramas dentales se muestran separadas de otros nervios craneales para facilitar su seguimiento.', 'Nervi signa sensoria et motoria ferunt; arteriae sanguinem afferunt et venae abducunt. Rami dentales separatim ab aliis nervis cranialibus ostenduntur ut cursus clarius sequantur.'], ['nerves', 'arterial-supply', 'venous-drainage'], trigeminal],
  ['nerves', ['The model includes dental branches of trigeminal V2 and V3, the main divisions of V, facial VII, and representative IX, X and XII courses. Use the nerve-group and side controls to study a manageable set.', 'Modellen innehåller dentala grenar från trigeminus V2 och V3, V:s huvudgrenar, facialis VII och representativa förlopp av IX, X och XII. Välj nervgrupp och sida för att studera färre förlopp samtidigt.', 'Das Modell umfasst dentale Äste von V2 und V3, die Hauptäste von V, VII sowie beispielhafte Verläufe von IX, X und XII. Wählen Sie Nervengruppe und Seite für eine übersichtliche Darstellung.', 'El modelo incluye ramas dentales de V2 y V3, divisiones principales de V, VII y trayectos representativos de IX, X y XII. Elija grupo y lado para estudiar un conjunto manejable.', 'Exemplar ramos dentales V2 et V3, divisiones principales V, VII et cursus exemplares IX, X et XII continet. Gregem nervorum et latus elige ut pauciores cursus simul studeas.'], ['trigeminal-nerves', 'facial-nerves', 'lower-cranial-nerves'], trigeminal],
  ['vessels', ['The arterial and venous pathways provide context for the nerves and jaws. Arteries are shown in red and veins in blue; translucent display helps distinguish overlapping structures.', 'Artär- och venförloppen ger sammanhang till nerver och käkar. Artärer visas röda och vener blå; genomskinlighet hjälper till att skilja överlappande strukturer.', 'Arterien und Venen zeigen die Gefäßbeziehungen zu Nerven und Kiefern. Arterien sind rot und Venen blau; Transparenz erleichtert die Unterscheidung überlagerter Strukturen.', 'Los trayectos arteriales y venosos muestran relaciones con nervios y maxilares. Las arterias se muestran rojas y las venas azules; la transparencia permite distinguir estructuras superpuestas.', 'Viae arteriarum et venarum nexus cum nervis et maxillis demonstrant. Arteriae rubrae et venae caeruleae ostenduntur; pelluciditas structuras superpositas distinguit.'], ['arterial-supply', 'venous-drainage'], skull],
  ['arterial-supply', ['The external carotid system supplies much of the face and oral region through branches including the maxillary and facial arteries. Dental branches travel close to their accompanying nerves.', 'Det externa karotissystemet försörjer stora delar av ansiktet och munregionen via bland annat a. maxillaris och a. facialis. Dentala grenar löper nära sina medföljande nerver.', 'Das äußere Karotissystem versorgt große Teile von Gesicht und Mundregion über Äste wie A. maxillaris und A. facialis. Dentale Äste verlaufen nahe den begleitenden Nerven.', 'El sistema carotídeo externo irriga gran parte de la cara y región oral mediante ramas como las arterias maxilar y facial. Las ramas dentales discurren cerca de sus nervios acompañantes.', 'Systema carotidis externae magnam partem faciei et regionis oris per ramos, inter quos arterias maxillarem et facialem, irrigat. Rami dentales prope nervos comitantes currunt.'], ['external-carotid-artery', 'maxillary-artery', 'facial-artery'], skull],
  ['muscles', ['Masseter, temporalis and the pterygoids act on the mandible. Buccinator, mentalis and orbicularis oris act on the cheeks and lips. These muscles have different roles even though they share one display layer.', 'Masseter, temporalis och pterygoideusmusklerna verkar på underkäken. Buccinator, mentalis och orbicularis oris verkar på kinder och läppar. Musklerna har olika uppgifter trots att de delar visningslager.', 'Masseter, Temporalis und Pterygoideusmuskeln bewegen den Unterkiefer. Buccinator, Mentalis und Orbicularis oris wirken auf Wangen und Lippen. Trotz gemeinsamer Anzeigeebene haben sie unterschiedliche Aufgaben.', 'Masetero, temporal y pterigoideos actúan sobre la mandíbula. Buccinador, mentoniano y orbicular de la boca actúan sobre mejillas y labios. Comparten una capa de visualización, pero tienen funciones distintas.', 'Masseter, temporalis et pterygoidei in mandibulam agunt. Buccinator, mentalis et orbicularis oris in genas et labia agunt. Musculi munera diversa habent quamquam in eodem strato ostenduntur.'], ['masseter', 'temporalis', 'lateral-pterygoid', 'orbicularis-oris'], supra],
  ['trigeminal-nerves', ['The trigeminal nerve (V) divides into ophthalmic V1, maxillary V2 and mandibular V3. V2 supplies the upper teeth and V3 the lower teeth; V3 also supplies the principal chewing muscles.', 'Trigeminusnerven (V) delar sig i ophthalmicus V1, maxillaris V2 och mandibularis V3. V2 ger känsel till överkäkens tänder och V3 till underkäkens; V3 innerverar även de viktigaste tuggmusklerna.', 'Der Trigeminus (V) teilt sich in V1, V2 und V3. V2 versorgt die oberen Zähne, V3 die unteren; V3 innerviert auch die wichtigsten Kaumuskeln.', 'El trigémino (V) se divide en oftálmico V1, maxilar V2 y mandibular V3. V2 da sensibilidad a dientes superiores y V3 a inferiores; V3 también inerva los principales músculos masticatorios.', 'Nervus trigeminus (V) in ophthalmicum V1, maxillarem V2 et mandibularem V3 dividitur. V2 dentes superiores et V3 inferiores sensibiliter innervant; V3 etiam musculos masticatorios principales innervat.'], ['trigeminal-nerve', 'maxillary-nerve', 'mandibular-nerve', 'ophthalmic-nerve'], trigeminal],
  ['facial-nerves', ['The facial nerve (VII) supplies the muscles of facial expression. Its temporal, zygomatic, buccal, marginal mandibular and cervical branch groups are shown separately from the sensory dental nerves.', 'Ansiktsnerven (VII) innerverar mimiska muskler. Temporala, zygomatiska, buckala, marginala mandibulära och cervikala grengrupper visas separat från tändernas känselnerver.', 'Der Gesichtsnerv (VII) versorgt die mimischen Muskeln. Seine temporalen, zygomatischen, bukkalen, marginal mandibulären und zervikalen Äste werden getrennt von den sensiblen Zahnnerven gezeigt.', 'El facial (VII) inerva los músculos de expresión facial. Sus grupos temporal, cigomático, bucal, marginal mandibular y cervical se muestran separados de los nervios sensitivos dentales.', 'Nervus facialis (VII) musculos mimicos innervat. Greges ramorum temporalium, zygomaticorum, buccalium, marginalium mandibularium et cervicalium separatim a nervis sensoriis dentalibus ostenduntur.'], ['facial-nerve', 'buccinator', 'orbicularis-oris'], facial],
  ['lower-cranial-nerves', ['Representative head and upper-neck courses of glossopharyngeal IX, vagus X and hypoglossal XII are grouped here. Their full distributions extend beyond this model; they do not replace the trigeminal dental supply.', 'Här grupperas representativa förlopp i huvud och övre hals av glossopharyngeus IX, vagus X och hypoglossus XII. Deras fulla utbredning går utanför modellen; de ersätter inte trigeminus tänders innervation.', 'Hier sind beispielhafte Kopf- und obere Halsverläufe von IX, X und XII gruppiert. Ihre vollständigen Versorgungsgebiete reichen über das Modell hinaus; sie ersetzen nicht die dentale Versorgung durch V.', 'Se agrupan trayectos representativos de IX, X y XII en cabeza y cuello superior. Su distribución completa supera el modelo; no sustituyen la inervación dental del trigémino.', 'Cursus exemplares IX, X et XII in capite et collo superiore hic colliguntur. Distributio plena ultra exemplar extenditur; innervationem dentalem trigemini non substituunt.'], ['glossopharyngeal-nerve', 'vagus-nerve', 'hypoglossal-nerve'], lower],
];
for (const [key, summary, related, ref] of groups) entries[key] = { summary, related, sources: [ref] };
entries['arterial-supply'].sources = [{ title: 'NCBI: Carotid arteries', url: 'https://www.ncbi.nlm.nih.gov/books/NBK545238/' }];
entries['vessels'].sources = [...entries['arterial-supply'].sources, ...entries['venous-drainage'].sources];
entries['neurovascular'].sources = [trigeminal, ...entries['vessels'].sources];
entries['muscles'].sources = [{ title: 'NCBI: Mastication muscles', url: 'https://www.ncbi.nlm.nih.gov/books/NBK541027/' }, facial];
entries['lower-cranial-nerves'].sources = [lower, { title: 'NCBI: Hypoglossal nerve', url: 'https://www.ncbi.nlm.nih.gov/books/NBK532869/' }];

const parts: [string, Translation, string[], { title: string; url: string }][] = [
  ['masseter-superficial', ['The superficial part of masseter runs from the zygomatic arch to the outer mandibular angle and lower ramus. It elevates the mandible and assists protrusion.', 'Masseters ytliga del löper från okbågen till underkäksvinkelns utsida och nedre ramus. Den höjer underkäken och hjälper till med protrusion.', 'Der oberflächliche Masseter zieht vom Jochbogen zum äußeren Unterkieferwinkel und unteren Ramus. Er hebt den Unterkiefer und unterstützt die Protrusion.', 'La parte superficial del masetero va del arco cigomático al ángulo mandibular externo y ramo inferior. Eleva la mandíbula y ayuda a protruirla.', 'Pars superficialis masseteris ab arcu zygomatico ad angulum mandibulae externum et ramum inferiorem currit. Mandibulam elevat et protrusionem adiuvat.'], ['masseter-deep', 'zygomatic-bone', 'mandible'], { title: 'NCBI: Masseter', url: 'https://www.ncbi.nlm.nih.gov/books/NBK539869/' }],
  ['masseter-deep', ['The deep part of masseter lies beneath the superficial portion, from the zygomatic arch to the upper outer mandibular ramus. It contributes to jaw elevation and stabilization.', 'Masseters djupa del ligger under den ytliga delen, från okbågen till övre utsidan av underkäkens ramus. Den bidrar till käkhöjning och stabilisering.', 'Der tiefe Masseter liegt unter dem oberflächlichen Anteil und zieht vom Jochbogen zum oberen äußeren Unterkieferast. Er trägt zu Kieferhebung und Stabilisierung bei.', 'La parte profunda del masetero está bajo la superficial, del arco cigomático al ramo mandibular superior externo. Contribuye a elevar y estabilizar la mandíbula.', 'Pars profunda masseteris sub parte superficiali ab arcu zygomatico ad ramum mandibulae superiorem externum currit. Elevationem et stabilitatem mandibulae adiuvat.'], ['masseter-superficial', 'zygomatic-bone', 'mandible'], { title: 'NCBI: Masseter', url: 'https://www.ncbi.nlm.nih.gov/books/NBK539869/' }],
  ['lateral-pterygoid-upper', ['The superior head of lateral pterygoid arises from the sphenoid and attaches variably to the condylar neck and disc–capsule complex. It helps control the disc–condyle relationship during function; attachment patterns vary.', 'Pterygoideus lateralis övre huvud har ursprung på kilbenet och varierande fästen på kondylhalsen och skiv–kapselkomplexet. Det bidrar till kontroll av skivans och kondylens samspel; fästena varierar.', 'Der obere Kopf des lateralen Pterygoideus entspringt am Keilbein und setzt variabel an Kondylushals und Diskus-Kapsel-Komplex an. Er kontrolliert das Zusammenspiel von Diskus und Kondylus; Ansätze variieren.', 'La cabeza superior del pterigoideo lateral nace en el esfenoides y se inserta de forma variable en cuello condilar y complejo disco-cápsula. Ayuda a controlar la relación disco-cóndilo; las inserciones varían.', 'Caput superius pterygoidei lateralis ab osse sphenoidali oritur et varie collo condyli et complexui disci et capsulae inseritur. Nexum disci et condyli moderari adiuvat; insertiones variant.'], ['lateral-pterygoid-lower', 'articular-disc', 'mandibular-condyle', 'sphenoid-bone'], { title: 'NCBI: Lateral pterygoid', url: 'https://www.ncbi.nlm.nih.gov/books/NBK549799/' }],
  ['lateral-pterygoid-lower', ['The inferior head of lateral pterygoid runs from the lateral pterygoid plate to the pterygoid fovea on the mandibular condylar neck. Bilateral action contributes to forward movement and opening; one-sided action contributes to lateral movement.', 'Pterygoideus lateralis nedre huvud löper från lamina lateralis processus pterygoidei till fovea pterygoidea på underkäkens kondylhals. Bilateral aktivitet bidrar till framåtrörelse och öppning; ensidig aktivitet bidrar till sidorörelse.', 'Der untere Kopf des lateralen Pterygoideus zieht von der lateralen Flügelplatte zur Fovea pterygoidea am Kondylushals. Beidseitige Aktivität unterstützt Vorschub und Öffnung, einseitige Aktivität die Seitbewegung.', 'La cabeza inferior del pterigoideo lateral va de la lámina pterigoidea lateral a la fóvea pterigoidea del cuello condilar. La acción bilateral ayuda a protrusión y apertura; la unilateral, al movimiento lateral.', 'Caput inferius pterygoidei lateralis a lamina pterygoidea laterali ad foveam pterygoideam colli condyli currit. Actio bilateralis protrusionem et aperturam, unilateralis motum lateralem adiuvat.'], ['lateral-pterygoid-upper', 'mandibular-condyle', 'sphenoid-bone'], { title: 'NCBI: Lateral pterygoid', url: 'https://www.ncbi.nlm.nih.gov/books/NBK549799/' }],
  ['gingiva-upper', ['The upper gingiva surrounds the necks of the maxillary teeth and covers their supporting alveolar bone. Its palatal and facial surfaces form a continuous soft-tissue margin around the upper arch.', 'Överkäkens gingiva omger tandhalsarna och täcker det stödjande alveolarbenet. De palatinala och faciala ytorna bildar en sammanhängande mjukvävnadskant runt tandbågen.', 'Die obere Gingiva umgibt die Zahnhälse der Maxilla und bedeckt den stützenden Alveolarknochen. Ihre palatinalen und fazialen Flächen bilden einen zusammenhängenden Weichgewebsrand.', 'La encía superior rodea los cuellos de los dientes maxilares y cubre el hueso alveolar de soporte. Las superficies palatina y facial forman un margen continuo de tejido blando.', 'Gingiva superior colla dentium maxillarium circumdat et os alveolare sustentans tegit. Superficies palatinales et faciales marginem textus mollis continuum formant.'], ['gingiva', 'maxillary-alveolar-process'], gingiva],
  ['gingiva-lower', ['The lower gingiva surrounds the necks of the mandibular teeth and covers their supporting alveolar bone. It moves with the lower jaw and forms the facial and lingual margins of the lower arch.', 'Underkäkens gingiva omger tandhalsarna och täcker det stödjande alveolarbenet. Den följer underkäkens rörelser och bildar tandbågens faciala och linguala mjukvävnadskanter.', 'Die untere Gingiva umgibt die Zahnhälse der Mandibula und bedeckt den stützenden Alveolarknochen. Sie bewegt sich mit dem Unterkiefer und bildet die fazialen und lingualen Ränder.', 'La encía inferior rodea los cuellos de los dientes mandibulares y cubre el hueso alveolar de soporte. Se mueve con la mandíbula y forma los márgenes facial y lingual de la arcada.', 'Gingiva inferior colla dentium mandibularium circumdat et os alveolare sustentans tegit. Cum mandibula movetur et margines faciales lingualesque arcus inferioris format.'], ['gingiva', 'mandibular-alveolar-process'], gingiva],
];
for (const [key, summary, related, ref] of parts) entries[key] = { summary, related, sources: [ref] };

const quadrants: [string, Translation][] = [
  ['upper-right-quadrant', ['The upper right permanent quadrant is FDI quadrant 1: teeth 11–18, from the central incisor to the third molar. Right is the person’s right, seen on the viewer’s left in a front view.', 'Övre högra permanenta kvadranten är FDI-kvadrant 1: tänder 11–18, från central incisiv till visdomstand. Höger är personens höger, som syns till vänster framifrån.', 'Der obere rechte permanente Quadrant ist FDI-Quadrant 1 mit Zähnen 11–18 vom mittleren Schneidezahn bis zum Weisheitszahn. Rechts bedeutet die rechte Seite der Person, frontal links im Bild.', 'El cuadrante permanente superior derecho es el FDI 1: dientes 11–18, del incisivo central al tercer molar. Derecha es la del paciente, a la izquierda del observador en vista frontal.', 'Quadrans permanens superior dexter FDI 1 dentes 11–18 continet, ab incisivo centrali ad molarem tertium. Dexter est latus personae, observatori in visu frontali sinistrum.']],
  ['upper-left-quadrant', ['The upper left permanent quadrant is FDI quadrant 2: teeth 21–28, from the central incisor to the third molar. Left refers to the person’s left, not the viewer’s.', 'Övre vänstra permanenta kvadranten är FDI-kvadrant 2: tänder 21–28, från central incisiv till visdomstand. Vänster syftar på personens vänstra sida.', 'Der obere linke permanente Quadrant ist FDI-Quadrant 2 mit Zähnen 21–28 vom mittleren Schneidezahn bis zum Weisheitszahn. Links bezieht sich auf die Person.', 'El cuadrante permanente superior izquierdo es el FDI 2: dientes 21–28, del incisivo central al tercer molar. Izquierda se refiere al paciente.', 'Quadrans permanens superior sinister FDI 2 dentes 21–28 continet, ab incisivo centrali ad molarem tertium. Sinister ad latus personae refertur.']],
  ['lower-left-quadrant', ['The lower left permanent quadrant is FDI quadrant 3: teeth 31–38, from the central incisor to the third molar. It moves with the mandible during jaw opening.', 'Nedre vänstra permanenta kvadranten är FDI-kvadrant 3: tänder 31–38, från central incisiv till visdomstand. Den rör sig med underkäken när munnen öppnas.', 'Der untere linke permanente Quadrant ist FDI-Quadrant 3 mit Zähnen 31–38 vom mittleren Schneidezahn bis zum Weisheitszahn. Er bewegt sich beim Öffnen mit dem Unterkiefer.', 'El cuadrante permanente inferior izquierdo es el FDI 3: dientes 31–38, del incisivo central al tercer molar. Se mueve con la mandíbula al abrir la boca.', 'Quadrans permanens inferior sinister FDI 3 dentes 31–38 continet, ab incisivo centrali ad molarem tertium. Cum mandibula in apertura movetur.']],
  ['lower-right-quadrant', ['The lower right permanent quadrant is FDI quadrant 4: teeth 41–48, from the central incisor to the third molar. It moves with the mandible during jaw opening.', 'Nedre högra permanenta kvadranten är FDI-kvadrant 4: tänder 41–48, från central incisiv till visdomstand. Den rör sig med underkäken när munnen öppnas.', 'Der untere rechte permanente Quadrant ist FDI-Quadrant 4 mit Zähnen 41–48 vom mittleren Schneidezahn bis zum Weisheitszahn. Er bewegt sich beim Öffnen mit dem Unterkiefer.', 'El cuadrante permanente inferior derecho es el FDI 4: dientes 41–48, del incisivo central al tercer molar. Se mueve con la mandíbula al abrir la boca.', 'Quadrans permanens inferior dexter FDI 4 dentes 41–48 continet, ab incisivo centrali ad molarem tertium. Cum mandibula in apertura movetur.']],
];
for (const [key, summary] of quadrants) entries[key] = { summary, related: [key.startsWith('upper') ? 'maxillary-dentition' : 'mandibular-dentition'], sources: [] };

entries['infraorbital-foramen'] = {
  summary: ['The infraorbital foramen is an opening on the front of the maxilla below the orbital rim. The infraorbital nerve, artery and vein emerge here; the nerve supplies sensation to the lower eyelid, upper lip and part of the nose and cheek.', 'Foramen infraorbitale är en öppning på överkäkens framsida under ögonhålans kant. N. infraorbitalis samt artär och ven kommer ut här; nerven ger känsel till nedre ögonlocket, överläppen och delar av näsan och kinden.', 'Das Foramen infraorbitale ist eine Öffnung an der Maxillavorderseite unter dem Orbitarand. Hier treten Infraorbitalnerv, -arterie und -vene aus; der Nerv versorgt Unterlid, Oberlippe und Teile von Nase und Wange sensibel.', 'El agujero infraorbitario es una abertura anterior del maxilar bajo el borde orbitario. Por él salen nervio, arteria y vena infraorbitarios; el nervio da sensibilidad al párpado inferior, labio superior y parte de nariz y mejilla.', 'Foramen infraorbitale apertura in superficie anteriore maxillae infra marginem orbitae est. Nervus, arteria et vena infraorbitales hic exeunt; nervus palpebram inferiorem, labium superius et partes nasi et genae sensibiliter innervat.'],
  related: ['maxilla', 'infraorbital-nerve', 'maxillary-nerve'], sources: [skull, trigeminal],
};

export function supportingAnatomy(lang: Lang) {
  const i = LANGS.indexOf(lang);
  return Object.fromEntries(Object.entries(entries).map(([key, e]) => [key, { summary: e.summary[i], ...(e.function ? { function: e.function[i] } : {}), related: e.related, sources: e.sources }]));
}
